package net.fabricmc.loader.api; import java.util.*; import java.nio.file.*; public class FabricLoader {static final FabricLoader INSTANCE=new FabricLoader(); public static FabricLoader getInstance(){return INSTANCE;} public Path getConfigDir(){return Path.of(System.getProperty("java.io.tmpdir"),"dc-mock-config");} public Optional<Container> getModContainer(String s){return Optional.of(new Container());} public static class Container{public Metadata getMetadata(){return new Metadata();}} public static class Metadata{public Version getVersion(){return new Version();}} public static class Version{public String getFriendlyString(){return System.getProperty("mock.mc","1.21.1");}}}